module.exports = /*#__PURE__*/JSON.parse('{"Navigation":{"home":"Início","impressum":"Aviso Legal","privacy":"Política de Privacidade","contact":"Contato","language":"Idioma","terms":"Termos de Uso"},"Meta":{"title":"Wildscope: App de Identificação de Fauna e Exploração da Natureza com IA","description":"Descubra e identifique a vida selvagem com tecnologia de IA, explore a natureza com mapas offline e rastreie animais como um profissional. O seu companheiro de aventuras ao ar livre definitivo."},"Hero":{"title":"O Seu Companheiro Completo para Atividades ao Ar Livre","subtitle":"Descubra a vida selvagem, aprenda habilidades de sobrevivência e explore a natureza com identificação por IA, dados de espécies de todo o mundo e guias interativos.","appstore":"Baixar na App Store","playstore":"Disponível no Google Play","download_subtext":"Download gratuito com recursos premium disponíveis","feature_1":"Reconhecimento de Fauna e Flora por IA","feature_2":"Base de Dados Mundial de Espécies","feature_3":"Mapas e Navegação Offline","feature_4":"Guias e Habilidades de Sobrevivência","feature_5":"Alertas de Tempo e Segurança","feature_6":"Aprendizagem Interativa e Comunidade"},"About":{"title":"O seu Guia Completo de Identificação de Vida Selvagem e Natureza","paragraph1":"Experimente a natureza como nunca antes com a tecnologia avançada de IA do Wildscope. Seja a identificar plantas numa caminhada, a seguir o rasto de vida selvagem em áreas remotas ou a aprender sobre os ecossistemas locais, as nossas funcionalidades abrangentes funcionam perfeitamente online e offline.","bullet1":"Identificação instantânea de plantas, animais e fungos com IA","bullet2":"Mapas offline detalhados e guias de espécies para qualquer local","bullet3":"Aprendizagem interativa através de quizzes e modo de aventura","bullet4":"Navegação GPS e ferramentas de seguimento de vida selvagem","bullet5":"Comunidade global de entusiastas da natureza","paragraph2":"Desde passeios casuais na natureza até ao seguimento sério de vida selvagem, o Wildscope combina tecnologia de IA de ponta com ferramentas abrangentes para o exterior para melhorar cada experiência na natureza."},"Features":{"title":"Ferramentas Completas de Identificação de Vida Selvagem e Exploração da Natureza","feature1_title":"Reconhecimento Avançado de Espécies e Treinador de IA","feature1_desc":"Identifique instantaneamente milhares de espécies com o nosso sistema de reconhecimento alimentado por IA e receba orientação personalizada do seu guia de natureza de IA. O Treinador Wildscope responde a perguntas sobre o seu ambiente, fornece dicas de segurança e partilha conhecimento fascinante sobre espécies e ecossistemas locais.","feature1_point1":"Identificação de espécies em tempo real com IA","feature1_point2":"Orientação de natureza personalizada através do Treinador de IA","feature1_point3":"Alertas de segurança sensíveis ao contexto","feature2_title":"Ferramentas de Navegação e Segurança","feature2_desc":"Navegue com confiança com o nosso conjunto completo de ferramentas, que inclui mapas offline, navegação por bússola, dados meteorológicos e sistema de pontos de passagem. Perfeito para aventuras remotas e exploração de áreas selvagens.","feature2_point1":"Bússola com navegação por pontos de passagem","feature2_point2":"Atualizações meteorológicas em tempo real","feature2_point3":"Acesso a informações de emergência","feature3_title":"Análise de Habitat e Bio-Índice","feature3_desc":"Explore e compreenda ecossistemas com as nossas ferramentas avançadas de análise de habitat. Acompanhe os índices de biodiversidade, monitorize a distribuição de espécies e descubra locais de interesse para a vida selvagem na sua área.","feature3_point1":"Análise de habitat e bioma","feature3_point2":"Acompanhamento do índice de biodiversidade","feature3_point3":"Mapas de distribuição de espécies","feature4_title":"Guia de Sobrevivência Completo","feature4_desc":"Domine competências essenciais para atividades ao ar livre com os nossos guias de sobrevivência abrangentes. Aprenda a fazer nós, a construir abrigos, a fazer fogo e outras técnicas cruciais de sobrevivência na natureza.","feature4_point1":"Tutoriais interativos de nós","feature4_point2":"Técnicas de construção de abrigos","feature4_point3":"Métodos para fazer fogo","feature5_title":"Comunidade e Média da Natureza","feature5_desc":"Conecte-se com outros entusiastas da natureza através das nossas vibrantes funcionalidades de comunidade. Partilhe descobertas, mantenha-se atualizado com notícias da natureza e participe em desafios da comunidade.","feature5_point1":"Feed de fotografia da natureza","feature5_point2":"Notícias sobre vida selvagem e natureza","feature5_point3":"Desafios da comunidade","feature6_title":"Experiência de Aprendizagem Interativa","feature6_desc":"Aprenda e teste os seus conhecimentos através de quizzes envolventes, aventuras guiadas e percursos de aprendizagem personalizados. Acompanhe o seu progresso e ganhe conquistas à medida que domina as competências ao ar livre.","feature6_point1":"Quizzes de identificação de espécies","feature6_point2":"Aventuras guiadas na natureza","feature6_point3":"Conquistas baseadas em competências","img1_alt":"Reconhecimento de Fauna e Flora por IA","img1_desc":"Identifique espécies instantaneamente e aceda a informação detalhada","img2_alt":"Ferramentas de Navegação e Segurança","img2_desc":"Navegue com confiança utilizando o nosso conjunto de ferramentas completo","img3_alt":"Análise de Habitat e Bio-Índice","img3_desc":"Explore e compreenda os ecossistemas locais","img4_alt":"Guia de Habilidades de Sobrevivência","img4_desc":"Aprenda técnicas essenciais de sobrevivência ao ar livre","img5_alt":"Comunidade da Natureza","img5_desc":"Conecte-se e partilhe com outros entusiastas da natureza","img6_alt":"Aprendizagem Interativa","img6_desc":"Teste os seus conhecimentos e acompanhe o seu progresso"},"CallToAction":{"title":"Não Perca Outro Momento Incrível com a Vida Selvagem!","subtitle":"Junte-se a milhares de entusiastas da natureza que já estão a descobrir e a identificar a vida selvagem como nunca antes. Descarregue o Wildscope agora e transforme as suas aventuras ao ar livre!","appstore":"Obtenha na App Store","playstore":"Baixe na Play Store","button":"Comece a Sua Jornada Selvagem","playstoreLink":"https://play.google.com/store/apps/details?id=com.duselk.theoutdoorbible","benefits":["✓ Identificação Instantânea de Plantas e Animais","✓ Funciona Offline em Áreas Remotas","✓ Navegação e Rastreamento GPS","✓ Guia de Natureza Alimentado por IA","✓ Comunidade Global de Vida Selvagem"]},"Footer":{"copyright":"© {year} Wildscope. Todos os direitos reservados.","impressum":"Aviso Legal","privacy":"Política de Privacidade","contact":"Contato"},"CookieBanner":{"message":"Este site utiliza cookies para garantir que você tenha a melhor experiência no nosso site.","accept":"Aceitar","decline":"Recusar"},"ImpressumPage":{"title":"Aviso Legal","section1_title":"Informação de acordo com o § 5 TMG (lei alemã)","address":"Dustin Keßler<br />Kurt Schumacher Straße 93<br />46539 Dinslaken<br />Alemanha","contact_title":"Contato","contact_email":"Email: ","responsibility_title":"Responsável pelo conteúdo de acordo com o § 55 par. 2 RStV (lei alemã)","disclaimer_title":"Aviso de Isenção de Responsabilidade","disclaimer_text":"Os conteúdos do nosso site foram criados com o máximo cuidado. No entanto, não podemos garantir a exatidão, integridade e atualidade dos conteúdos. Como prestador de serviços, somos responsáveis pelo nosso próprio conteúdo nestas páginas, de acordo com as leis gerais, nos termos do § 7 par. 1 TMG (lei alemã). De acordo com os §§ 8 a 10 TMG (lei alemã), como prestador de serviços, não somos obrigados a monitorizar informações de terceiros transmitidas ou armazenadas, nem a investigar circunstâncias que indiquem atividade ilegal."},"PrivacyPage":{"content":"# Política de Privacidade para o Wildscope\\n\\nÚltima atualização: 06 de fevereiro de 2025\\n\\n## 2. Que Dados Recolhemos?\\nA maioria dos dados é armazenada localmente no seu dispositivo. Os dados só são guardados na nuvem ou em serviços externos quando utiliza funcionalidades específicas.\\n\\n### 📍 Dados de Localização e Atividade\\n• A maior parte do processamento de localização ocorre localmente no seu dispositivo.\\n• Armazenamos os países, biomas, reinos e ecorregiões visitados no seu perfil de utilizador (sem dados de GPS ou de localização exata).\\n• Os dados de localização só são enviados para serviços externos quando determinadas funcionalidades são utilizadas:\\n  - APIs do Google Maps, Places e Geocoding: Mapas, preenchimento automático e pesquisa de POI.\\n  - Mapbox: Estilos de mapa, mosaicos e navegação (utilizadores Premium).\\n  - OpenStreetMap (OSM): Pesquisa de POI e dados de mapa.\\n  - GBIF: Consulta de animais e plantas na sua região.\\n  - OpenWeather e RainViewer: Dados meteorológicos e de radar.\\n  - Open Elevation e OpenTopo: Análise de terreno.\\n  - Google Gemini e OpenAI: Funcionalidades de IA (ex: quiz, modo de aventura).\\n\\n### 💾 Firebase para Armazenamento e Autenticação\\n\\n• Utilizamos o Firebase (região de Frankfurt) para autenticação de utilizadores e armazenamento de dados.\\n\\n• Dados como contas de utilizador, publicações, comentários, uploads e regiões visitadas são armazenados no Firebase.\\n\\n• O Firebase implementa os seus próprios controlos de segurança e acesso para proteger os seus dados.\\n\\n• Pode solicitar a eliminação completa da sua conta e dos dados associados a qualquer momento.\\n\\n### 📊 Análise do PostHog e Utilização da Aplicação\\n\\n• Utilizamos o PostHog para estatísticas de utilização anonimizadas.\\n\\n• O PostHog ajuda-nos a compreender e a melhorar a utilização da aplicação.\\n\\n• Os dados recolhidos incluem: ecrãs visitados, interações com a aplicação, duração da sessão.\\n\\n• Nenhum dado pessoal é associado à sua conta.\\n\\n• Pode desativar o rastreio a qualquer momento nas definições.\\n\\n### 👤 Conta de Utilizador e Dados do Perfil\\n\\n• É necessário registo.\\n\\n• Armazenamento de: nome de utilizador, endereço de e-mail, estado premium.\\n\\n• As palavras-passe são armazenadas de forma encriptada.\\n\\n### 📤 Uploads e Interações\\nOs dados só são armazenados na nuvem quando:\\n\\n• Partilha uma imagem ou vídeo: Nome de utilizador, data e local da captura.\\n\\n• Cria uma publicação: O texto é armazenado, mas não a sua localização.\\n\\n• Gosta ou comenta: Apenas a própria interação é armazenada.\\n\\n### 🎥 Serviços de Terceiros e APIs\\n\\n• Mapas e Localização: Google Maps, Places, APIs de Geocoding e Mapbox (utilizadores Premium).\\n\\n• Dados da Natureza: GBIF para informação de espécies, PlantNet para identificação de plantas.\\n\\n• Meteorologia: OpenWeather e RainViewer para dados meteorológicos.\\n\\n• Terreno: Open Elevation e OpenTopo para dados de elevação.\\n\\n• Conteúdo: Vídeos do YouTube, artigos e imagens da Wikipedia/Wikimedia.\\n\\n• Serviços de IA: Google Gemini e OpenAI para funcionalidades interativas.\\n\\n• Cada serviço processa os dados de acordo com as suas próprias políticas de privacidade.\\n\\n• As funcionalidades Premium utilizam o RevenueCat para o processamento de pagamentos.\\n\\n### 📺 Utilização dos Serviços da API do YouTube\\nA nossa aplicação utiliza os Serviços da API do YouTube para lhe fornecer conteúdo de vídeo relacionado com atividades ao ar livre, natureza e habilidades de sobrevivência. Ao utilizar a nossa funcionalidade de Feed de Média, reconhece e concorda em vincular-se aos Termos de Serviço do YouTube (https://www.youtube.com/t/terms) e à Política de Privacidade da Google (http://www.google.com/policies/privacy).\\n\\n#### Recolha e Acesso a Dados\\nQuando utiliza a nossa funcionalidade de Feed de Média, acedemos e recolhemos as seguintes informações através dos Serviços da API do YouTube:\\n\\nDa API do YouTube:\\n\\n• Metadados públicos de vídeos, incluindo títulos, descrições, miniaturas, nomes de canais e datas de publicação.\\n• URLs e identificadores de vídeos.\\n• Resultados de pesquisa baseados na sua localização и categorias de conteúdo selecionadas.\\n\\nDo Seu Dispositivo:\\n\\n• Os seus dados de localização (quando os feeds baseados na localização estão ativados) para fornecer conteúdo de vídeo geograficamente relevante.\\n• Preferências e definições da aplicação armazenadas localmente no seu dispositivo.\\n• Dados de vídeo em cache armazenados temporariamente no armazenamento local do seu dispositivo.\\n\\n#### Armazenamento e Colocação em Cache de Dados\\n\\n• Os metadados de vídeo obtidos da API do YouTube são colocados em cache localmente no seu dispositivo por até 24 horas para melhorar o desempenho da aplicação e reduzir o uso de dados.\\n\\n• Os dados em cache incluem detalhes do vídeo, carimbos de data/hora, categorias selecionadas, âmbito da localização e informação de localização.\\n\\n• Nenhuns dados de autenticação do utilizador ou informação pessoal da conta do YouTube são armazenados.\\n\\n• Todos os dados em cache são armazenados localmente no seu dispositivo utilizando o AsyncStorage e não são transmitidos para servidores externos.\\n\\n#### Utilização e Processamento de Dados\\nUtilizamos a informação recolhida para:\\n\\n• Exibir conteúdo de vídeo relevante sobre atividades ao ar livre e natureza no nosso Feed de Média.\\n\\n• Fornecer recomendações de vídeo baseadas na localização quando ativa os feeds de localização.\\n\\n• Colocar conteúdo em cache localmente para melhorar o desempenho da aplicação e a capacidade offline.\\n\\n• Filtrar e ordenar os resultados de vídeo com base nas suas preferências e localização.\\n\\n#### Partilha de Dados e Terceiros\\n\\n• Não partilhamos quaisquer dados de utilizador ou da API do YouTube com terceiros para fins comerciais.\\n\\n• As interações de vídeo dentro de leitores de vídeo do YouTube incorporados estão sujeitas às próprias práticas de privacidade do YouTube e podem ser rastreadas pela Google/YouTube.\\n\\n• A nossa aplicação utiliza as suas próprias credenciais da API do YouTube e não acede à sua conta pessoal do YouTube.\\n\\n• Os dados de localização utilizados para pesquisas de vídeo são processados localmente e combinados com termos de pesquisa públicos.\\n\\n#### Cookies e Informação do Dispositivo\\n\\n• Ao visualizar vídeos do YouTube incorporados, o YouTube pode colocar cookies ou tecnologias semelhantes no seu dispositivo, de acordo com as práticas de privacidade da Google.\\n\\n• A nossa aplicação acede ao armazenamento local do dispositivo (AsyncStorage) para colocar conteúdo de vídeo em cache e guardar as preferências do utilizador.\\n\\n• Poderemos recolher informação do dispositivo necessária para a funcionalidade da aplicação, incluindo dados de localização para funcionalidades baseadas na localização.\\n\\n#### Retenção de Dados\\n\\n• Os metadados de vídeo em cache local são eliminados automaticamente após 24 horas.\\n\\n• As preferências e definições do utilizador permanecem armazenadas localmente até que desinstale a aplicação ou limpe manualmente os dados da aplicação.\\n\\n• Nenhuns dados da API do YouTube são armazenados permanentemente em servidores externos.\\n\\n#### Direitos e Controlo do Utilizador\\nPode:\\n\\n• Desativar os feeds de vídeo baseados na localização nas definições da aplicação.\\n• Limpar os dados em cache atualizando o Feed de Média ou limpando o armazenamento da aplicação.\\n• Aceder aos vídeos do YouTube diretamente através da aplicação ou do site do YouTube, onde se aplicam os controlos de privacidade da Google.\\n• Contactar-nos para solicitar informação sobre os dados recolhidos através da nossa aplicação.\\n\\n#### Políticas de Privacidade de Terceiros\\nAo utilizar os Serviços da API do YouTube na nossa aplicação, está também sujeito a:\\n\\n• Política de Privacidade da Google: http://www.google.com/policies/privacy\\n• Termos de Serviço do YouTube: https://www.youtube.com/t/terms\\n\\n### 🤖 Consentimento de IA\\nCertas funcionalidades desta aplicação utilizam serviços de IA fornecidos pela OpenAI e/ou Google Gemini. Estes serviços podem processar os dados do utilizador fora da UE. Nenhuma funcionalidade de IA está ativada por defeito. Ao ativar explicitamente as funcionalidades de IA na aplicação, está a dar o seu consentimento nos termos do Art. 6(1)(a) do RGPD. Pode retirar este consentimento a qualquer momento através das definições da aplicação.\\n\\n## 3. Porque Processamos os Seus Dados?\\nBases legais de acordo com o RGPD:\\n\\n• Art. 6(1)(a) (Consentimento): Partilha de localização, utilização de IA, uploads.\\n\\n• Art. 6(1)(b) (Execução de contrato): Conta de utilizador e adesão premium.\\n\\n• Art. 6(1)(f) (Interesse legítimo): Melhoria da aplicação através da análise do PostHog.\\n\\n## 4. Armazenamento e Eliminação de Dados\\nOnde são armazenados os seus dados?\\n\\n• Dados de localização: Localmente, não armazenados permanentemente.\\n\\n• Publicações, gostos, uploads: No Firebase (região de Frankfurt), se partilhados ativamente.\\n\\n• Dados de análise: Anonimizados através do PostHog.\\n\\n• A maioria dos dados da aplicação é armazenada localmente no seu dispositivo.\\n\\n• Servidores backend: Localizados nos EUA e na Europa (Heroku).\\n\\n• Identificação de plantas: API da PlantNet (serviço externo).\\n\\n• Feed de notícias: API do Google News.\\n\\n• Processamento de pagamentos: RevenueCat (sem armazenamento direto de dados de pagamento).\\n\\nEliminação de dados:\\n\\n• Todos os dados podem ser eliminados nas definições da aplicação.\\n\\n• A eliminação da conta remove todos os dados associados no Firebase.\\n\\n## 5. Quem Tem Acesso aos Seus Dados?\\n\\n• Nenhuma partilha para fins publicitários.\\n\\n• Os dados de localização são apenas enviados temporariamente para serviços externos.\\n\\n• O YouTube e a Wikimedia recolhem os seus próprios dados quando utilizados.\\n\\n• O PostHog processa estatísticas de utilização anónimas.\\n\\n• As APIs da Google são utilizadas para várias funções.\\n\\n• Nenhum armazenamento de dados de pagamento (Google Play / Apple Pay).\\n\\n## 6. Os Seus Direitos ao Abrigo do RGPD\\n\\n• Informação sobre os dados armazenados.\\n\\n• Correção de dados incorretos.\\n\\n• Eliminação dos seus dados.\\n\\n• Portabilidade dos dados.\\n\\n• Retirada do consentimento a qualquer momento.\\n\\n📧 Contacto para questões de privacidade: duselkay@gmail.com\\n\\n## 1. Parte Responsável\\nDustin Keßler\\nEndereço: Kurt Schumacher Straße 93, 46539 Dinslaken\\nEmail: duselkay@gmail.com"},"TermsPage":{"title":"Termos de Uso","content":"# Termos de Uso\\n\\nÚltima atualização: 06 de março de 2025\\n\\n## 1. Geral\\nEstes Termos de Uso regem a utilização da aplicação Wildscope. Ao criar uma conta, concorda com estes termos. A idade mínima para utilização é de 16 anos. A aplicação oferece funcionalidades de seguimento de vida selvagem, identificação de plantas e exploração da natureza, concebidas para melhorar a sua experiência ao ar livre.\\n\\n## 2. Funcionalidades da Aplicação\\nO Wildscope fornece dados baseados na localização para animais, plantas, pontos de interesse e informação meteorológica. A aplicação inclui funcionalidades alimentadas por IA, como quizzes sobre a natureza e modo de aventura, a capacidade de carregar fotos e vídeos, criar publicações e aceder a funcionalidades premium para conteúdo adicional e funcionalidades melhoradas.\\n\\n## 3. Conta de Utilizador e Responsabilidade\\nÉ responsável por manter a segurança da sua conta e por usar uma palavra-passe segura. Os utilizadores devem cumprir todas as leis e regulamentos aplicáveis ao usar a aplicação.\\n\\n### Conteúdo Proibido\\nÉ proibido aos utilizadores publicar conteúdo ilegal, ofensivo ou protegido por direitos de autor. A manipulação de dados de localização é estritamente proibida. A eliminação da conta está disponível a qualquer momento através das definições da aplicação.\\n\\n## 4. Gestão de Dados Técnicos\\nA maioria dos dados é armazenada localmente no seu dispositivo para um desempenho e privacidade ótimos. O Firebase é utilizado para autenticação e armazenamento na nuvem quando necessário. O PostHog fornece análises de utilização anonimizadas para melhorar a aplicação. As APIs da Google permitem várias funcionalidades da aplicação. Não utilizamos os seus dados para fins publicitários.\\n\\n## 5. Adesão Premium\\nAs funcionalidades premium estão disponíveis através do Google Play ou Apple Pay. Não há direito de rescisão após a utilização das funcionalidades premium. As subscrições premium podem ser canceladas a qualquer momento através da sua respetiva loja de aplicações.\\n\\n## 6. Aviso de Isenção de Responsabilidade\\n### Limitação de Responsabilidade\\nNão assumimos qualquer responsabilidade por:\\n• Informação incorreta ou desatualizada sobre plantas, animais ou pontos de interesse.\\n• Danos resultantes da aplicação incorreta de dicas de sobrevivência ou informação relacionada com a natureza.\\n• Perda de dados, avarias da aplicação ou indisponibilidade temporária de funcionalidades.\\n• Violações de segurança de dados resultantes de fornecedores terceiros.\\n• Conteúdo gerado por IA e decisões baseadas no mesmo — todos os resultados de IA (texto, imagens, áudio, sugestões) são gerados sem garantias de exatidão, segurança ou adequação. Utilize por sua conta e risco, especialmente em situações de emergência ou sobrevivência.\\n\\n### Conteúdo de IA e Utilização em Sobrevivência\\nO Wildscope inclui funcionalidades experimentais alimentadas por IA, fornecidas por serviços de terceiros como o OpenAI e o Google Gemini. Estas funcionalidades podem gerar conteúdo impreciso, enganoso ou inadequado. Não confie em conteúdo gerado por IA para emergências, sobrevivência ou decisões críticas de segurança. Declinamos toda a responsabilidade por resultados decorrentes de decisões baseadas em conteúdo de IA.\\n\\n## 7. Direitos de Conteúdo\\n### Conteúdo Gerado pelo Utilizador\\nTodos os uploads e conteúdo gerado pelo utilizador permanecem propriedade do utilizador. O conteúdo é privado por defeito, a menos que seja partilhado explicitamente. O conteúdo ilegal será removido sem aviso prévio.\\n\\n### Conteúdo da Aplicação e Direitos de Autor\\nTodo o conteúdo da aplicação, incluindo dados, textos e gráficos, está protegido por direitos de autor. O uso comercial do conteúdo da aplicação é estritamente proibido sem permissão por escrito.\\n\\n## 8. Integração com o YouTube\\nA nossa aplicação integra-se com os Serviços de API do YouTube para fornecer conteúdo de vídeo. A sua utilização de quaisquer funcionalidades relacionadas com o YouTube está sujeita aos Termos de Serviço do YouTube (https://www.youtube.com/t/terms), que são incorporados por referência nestes Termos de Uso.\\n\\n### Utilização Aceitável\\nAo utilizar a nossa funcionalidade de Feed de Média, concorda em:\\n• Cumprir os Termos de Serviço e as Diretrizes da Comunidade do YouTube.\\n• Utilizar o conteúdo de vídeo apenas para fins pessoais e não comerciais.\\n• Não tentar descarregar, extrair ou redistribuir conteúdo do YouTube fora da funcionalidade pretendida da aplicação.\\n• Respeitar os direitos de propriedade intelectual dos criadores de vídeo e do YouTube.\\n\\n### Aviso de Isenção de Responsabilidade do YouTube\\n• Não somos responsáveis pela exatidão, legalidade ou adequação do conteúdo do YouTube exibido na nossa aplicação.\\n• O conteúdo de vídeo é fornecido por criadores de terceiros e não reflete necessariamente as nossas opiniões.\\n• A disponibilidade e funcionalidade do conteúdo do YouTube podem mudar sem aviso prévio devido a políticas ou alterações técnicas do YouTube.\\n\\n### Acordo de Processamento de Dados\\nAo utilizar os Serviços de API do YouTube através da nossa aplicação, reconhece que:\\n• A Google/YouTube podem processar os seus dados de interação de acordo com as suas políticas de privacidade.\\n• Os leitores de vídeo incorporados podem recolher dados de análise e utilização diretamente através dos sistemas do YouTube.\\n• Atuamos como um processador de dados para os dados da API do YouTube e não controlamos as práticas de dados do YouTube.\\n\\n## 9. Reembolsos\\nTodos os pagamentos são geridos através do Google Play ou da App Store da Apple. Cumprimos as suas respetivas políticas de reembolso.\\n\\nNão oferecemos reembolsos em casos que incluam:\\n• Funcionalidades de IA ou média indisponíveis devido ao esgotamento de quotas.\\n• Problemas temporários causados por interrupções de API de terceiros.\\n• Incompatibilidade com o dispositivo do utilizador ou falta de acesso à internet.\\n\\nOs utilizadores são responsáveis por cancelar as subscrições através da sua respetiva loja antes da renovação. Não podemos intervir nos sistemas de faturação baseados na plataforma.\\n\\n## 10. Serviços de Terceiros e Limitações de API\\nO Wildscope depende de APIs e plataformas de terceiros para fornecer muitas das suas funcionalidades. Estes serviços estão sujeitos a limites de taxa, interrupções e restrições de utilização — o que pode afetar tanto os utilizadores gratuitos como os premium.\\n\\n**Os serviços externos incluem:**\\n• APIs da Google (Mapas, Locais, Geocodificação, Mapas Estáticos)\\n• Mapbox (Mosaicos, Estilos, Navegação)\\n• PlantNet (Identificação de plantas)\\n• API de Dados do YouTube\\n• APIs da Wikipedia / Wikimedia\\n• OpenStreetMap / Overpass\\n• GBIF (Biodiversidade Global)\\n• RainViewer e OpenWeatherMap (Meteorologia e radar)\\n• Open Elevation e OpenTopo\\n• RevenueCat (Gestão de pagamentos na aplicação)\\n• Firebase (autenticação, nuvem, Firestore)\\n• OpenAI e Google Gemini (serviços de IA)\\n\\nO Wildscope não é responsável por interrupções, desempenho degradado ou limitações de funcionalidades causadas por restrições de serviços de terceiros. Exemplos:\\n• O nível gratuito do PlantNet está limitado a 500 identificações/dia.\\n• O acesso ao OpenAI ou Gemini pode ficar indisponível devido a limites de quota ou custos.\\n• As funcionalidades do Mapbox podem ser restringidas assim que os limites mensais de mosaicos forem atingidos.\\n\\n## 11. Notas Legais\\n• O Wildscope não garante a exatidão, integridade ou fiabilidade de qualquer conteúdo, recomendação ou conselho.\\n• Todas as funcionalidades da aplicação — incluindo IA, mapas, ferramentas de identificação — são apenas para fins informativos e de entretenimento.\\n• O Wildscope não é uma ferramenta de emergência ou médica certificada e não deve ser considerada como tal.\\n• Os utilizadores são responsáveis por cumprir os regulamentos locais ao utilizar funcionalidades que envolvem dados de espécies, geolocalização ou partilha de conteúdo.\\n\\n## 12. Alterações aos Termos de Uso\\nA utilização contínua da aplicação após as atualizações destes termos implica a aceitação da nova versão. Os utilizadores serão notificados de alterações materiais através de notificações na aplicação ou por e-mail.\\n\\n## 13. Contacto\\nPara suporte ou questões sobre estes termos, contacte-nos em: duselkay@gmail.com"},"ContactPage":{"title":"Contacte-nos","contact_intro":"Sinta-se à vontade para entrar em contacto connosco para quaisquer questões, feedback ou perguntas.","contact_person":"Pessoa de contacto","country":"Alemanha"},"NotFound":{"title":"Página Não Encontrada","description":"Desculpe, a página que procura não existe ou foi movida.","backHome":"Voltar à Página Inicial"},"General":{"loading":"A carregar...","comingSoon":"Em Breve"},"FAQ":{"title":"Perguntas Frequentes Sobre o Seguimento de Vida Selvagem","question1":"Como é que o Wildscope se compara a outras aplicações de identificação da natureza como o iNaturalist?","answer1":"Enquanto o iNaturalist se foca principalmente na identificação de espécies e na ciência cidadã, o Wildscope oferece uma experiência completa ao ar livre com funcionalidades adicionais concebidas especificamente para entusiastas da natureza. A nossa aplicação inclui identificação de vida selvagem offline, ferramentas de navegação GPS para exploração de áreas selvagens, aprendizagem interativa através de quizzes sobre a natureza e um companheiro de IA que compreende o seu ambiente para fornecer orientação personalizada—tornando-a perfeita tanto para amantes casuais da natureza como para seguidores sérios de vida selvagem.","question2":"Posso identificar plantas e animais offline com o Wildscope?","answer2":"Parcialmente. A análise de IA requer uma ligação à internet, mas verá todas as espécies seguidas da sua área exibidas e pode usá-las para ajudar na identificação.","question3":"Que dispositivos suportam a aplicação de exploração da natureza Wildscope?","answer3":"As funcionalidades de seguimento de vida selvagem e identificação da natureza do Wildscope estão disponíveis para dispositivos iOS (iPhone/iPad) e Android através da App Store e da Google Play Store, tornando-a acessível a praticamente todos os utilizadores de smartphones.","question4":"A aplicação de identificação de vida selvagem Wildscope é gratuita?","answer4":"O Wildscope oferece uma versão gratuita com funcionalidades essenciais de identificação de vida selvagem e exploração da natureza. A nossa subscrição premium desbloqueia capacidades avançadas como descobertas ilimitadas de espécies, mais créditos, mais locais personalizados para visitar e benefícios adicionais. Verifique a aplicação para as opções de subscrição atuais.","question5":"Quão precisa é a identificação de plantas e animais do Wildscope?","answer5":"O Wildscope combina dados de localização com tecnologia avançada de IA para identificar vida selvagem e plantas com alta precisão. Embora o nosso sistema de reconhecimento melhore continuamente, a precisão da identificação varia por espécie, qualidade da imagem e ângulo de visão. Estamos constantemente a melhorar os nossos algoritmos através de atualizações regulares para fornecer uma identificação de vida selvagem e plantas cada vez mais precisa em todos os ambientes.","question6":"Posso contribuir para a base de dados de vida selvagem do Wildscope?","answer6":"Com certeza! O Wildscope prospera com as contribuições da comunidade. As suas observações de vida selvagem e identificações de plantas são adicionadas de forma segura à nossa base de dados do ecossistema, melhorando a precisão da aplicação para todos. Esta abordagem colaborativa cria um recurso abrangente de identificação de vida selvagem que beneficia todos os entusiastas da natureza.","question7":"O Wildscope é desenvolvido por uma grande empresa de tecnologia?","answer7":"Não, o Wildscope é um projeto independente desenvolvido por um entusiasta da natureza dedicado. A aplicação é concebida e mantida por um único programador apaixonado que prioriza a precisão e a experiência do utilizador em detrimento da monetização. Esta abordagem independente garante que o Wildscope se mantenha fiel à sua missão principal: ajudar as pessoas a conectarem-se e a compreenderem a natureza sem comprometer a privacidade ou a experiência do utilizador."},"OfflineCapabilities":{"title":"Capacidades Offline – Explore Sem Limites","intro":"Depois de carregar uma área, pode desfrutar de uma exploração completa mesmo sem acesso à internet:","capability1":"Mapas e Trilhos Offline","capability2":"Dados de Espécies Locais e Monumentos Naturais","capability3":"POIs e Destaques Adicionados pela Comunidade","libraries_title":"Bibliotecas de Conhecimento:","library1":"Plantas Comestíveis","library2":"Técnicas de Navegação","library3":"Noções Básicas de Primeiros Socorros","library4":"Construção de Abrigos","library5":"Guias de Fogo e Água","library6":"Bússola, Ferramenta Morse e mais","library7":"Quizzes Básicos sobre a Natureza"},"OnlineFeatures":{"title":"Funcionalidades Online – Melhoradas por IA","intro":"Mantenha-se conectado para uma experiência completa:","feature1_title":"Treinador Wildscope","feature1_desc":"Pergunte sobre o seu ambiente, carregue imagens e obtenha orientação personalizada.","feature2_title":"Identificação Potenciada por IA","feature2_desc":"Reconheça espécies instantaneamente usando fotos e aceda a informação detalhada e consciente da localização.","feature3_title":"Informações Inteligentes","feature3_desc":"Aprenda sobre a história local, descobertas da comunidade, padrões sazonais e mais.","feature4_title":"Comunidade Global e Partilha","feature4_desc":"Partilhe as suas descobertas, siga avistamentos raros e explore percursos curados por utilizadores.","feature5_title":"Quizzes e Aventuras de Texto Baseados na Localização","feature5_desc":"Interaja com o seu ambiente através de experiências ricas e imersivas."},"Audience":{"title":"Para Quem é o Wildscope?","intro":"Quer seja um explorador experiente ou esteja apenas a começar a sua jornada na natureza, o Wildscope é para si:","audience1_title":"Caminhantes e Excursionistas","audience1_desc":"Navegue por trilhos, identifique espécies e mantenha-se seguro com mapas offline e ferramentas de sobrevivência.","audience2_title":"Fotógrafos de Vida Selvagem e Observadores de Aves","audience2_desc":"Descubra, siga e identifique espécies esquivas para capturar aquela foto perfeita.","audience3_title":"Famílias e Exploradores Casuais","audience3_desc":"Transforme as visitas ao parque em emocionantes aventuras de aprendizagem para todas as idades.","audience4_title":"Educadores e Estudantes","audience4_desc":"Uma ferramenta poderosa para a educação ao ar livre, projetos de biodiversidade e estudos da natureza.","audience5_title":"Sobrevivencialistas e Praticantes de Bushcraft","audience5_desc":"Aperfeiçoe as suas competências com a identificação de plantas, guias de construção de abrigos e recursos offline.","conclusion":"E para qualquer pessoa com curiosidade sobre o mundo natural!"},"Testimonials":{"title":"O Que Dizem os Nossos Exploradores","testimonial1":"O Wildscope mudou completamente a minha forma de explorar. Os mapas offline são um salva-vidas, e a identificação por IA é incrivelmente precisa!","testimonial1_author":"Sara L.","testimonial1_role":"Entusiasta de Caminhadas","testimonial2":"Como professor de biologia, esta aplicação é uma ferramenta fantástica para os meus alunos. Torna a aprendizagem sobre a flora e fauna locais muito mais interativa.","testimonial2_author":"David K.","testimonial2_role":"Educador"},"Pricing":{"title":"Escolha o Seu Plano Wildscope","free_title":"Explorador Básico","free_subtitle":"Comece a sua jornada com as funcionalidades essenciais.","free_price":"Grátis","free_price_suffix":"Para Sempre","free_feature1":"Identificação de Espécies por IA (limitada)","free_feature2":"Mapas Regionais Offline (1 região)","free_feature3":"Acesso ao Guia de Sobrevivência Básico","free_feature4":"Acesso ao Fórum da Comunidade","free_feature5":"Seguimento de 5 POIs Favoritos","free_feature_limited1":"Experiência com Anúncios","free_cta":"Incluído no Download","pro_badge":"Melhor Valor","pro_title":"Wildscope Pro","pro_subtitle":"Desbloqueie todo o poder da exploração da natureza.","pro_price":"2,99 €","pro_price_suffix":"por mês (ou 17,99 €/ano)","pro_feature1":"Identificação Ilimitada de Espécies por IA","pro_feature2":"Mapas Regionais Offline Ilimitados","pro_feature3":"Guia de Sobrevivência Completo e Ferramentas Avançadas","pro_feature4":"Funcionalidades Premium da Comunidade","pro_feature5":"Seguimento Ilimitado de POIs Favoritos","pro_feature6":"Experiência Sem Anúncios","pro_feature7":"Suporte Prioritário","pro_cta":"Torne-se Pro e Explore Mais","footnote":"Os preços podem variar por região. As subscrições são geridas através da App Store/Google Play."}}');

